-- SG practical scenario expansion: 37 existing rows are rewritten in Japanese; 363 new Japanese scenarios bring the seeded total to 400.
-- All scenarios are original authored practice, not official IPA questions. Existing IDs are preserved for scenario_attempts foreign keys.
PRAGMA foreign_keys = ON;

UPDATE practical_scenarios SET
  title = '不審メールへの対応：導入前の確認',
  category = 'メール・フィッシング対策',
  difficulty = 'intermediate',
  situation = '社員に、送信元ドメインが正規の会社と一文字だけ異なる認証メールが届いた。',
  task = 'この状況で、最も適切な初動対応はどれか（このケースで）',
  options_json = '[{"id":"a","text":"リンクや添付ファイルを開かず、既知の連絡先で独立して真偽を確認し、組織の手順に従って報告する。"},{"id":"b","text":"急ぎの依頼なので、リンク先で内容を確認してから判断する。"},{"id":"c","text":"同僚全員へそのメールを転送し、各自で安全性を判断してもらう。"},{"id":"d","text":"証拠を残さないようメールを削除し、報告は行わない。"}]',
  best_option = 'a',
  scoring_json = '{"a":100,"b":35,"c":15,"d":0}',
  explanation = '表示名や署名だけでは送信者の真正性を確認できない。リンクや添付を開かず、既知の連絡手段で独立確認し、報告と証拠保全を行う。',
  source_type = 'authored'
WHERE id = 'sg-scenario-phishing-001' AND track_id = 'exam-sg';

UPDATE practical_scenarios SET
  title = '特権アカウントの管理：導入前の確認',
  category = 'アクセス制御・特権管理',
  difficulty = 'standard',
  situation = '一般社員の開発用アカウントに、本番サーバの管理者権限が付与されている。',
  task = '最小権限と操作の追跡可能性を両立する方法はどれか（このケースで）',
  options_json = '[{"id":"a","text":"作業効率を優先し、管理者権限を全員へ付与する。"},{"id":"b","text":"監査を簡単にするため、全員が同じ管理者IDを使う。"},{"id":"c","text":"個人を識別できるID、必要最小限かつ期限付きの権限、承認記録、特権操作ログを組み合わせる。"},{"id":"d","text":"設定ミスを避けるため、付与済みの権限は定期的に見直さない。"}]',
  best_option = 'c',
  scoring_json = '{"a":35,"b":15,"c":100,"d":0}',
  explanation = '特権は職務に必要な範囲に限定し、個人を識別できる形で付与する。承認、期限、操作ログ、定期レビューを組み合わせて追跡可能性を確保する。',
  source_type = 'authored'
WHERE id = 'sg-scenario-access-001' AND track_id = 'exam-sg';

UPDATE practical_scenarios SET
  title = 'インシデント対応と証拠保全：導入前の確認',
  category = 'インシデント対応',
  difficulty = 'intermediate',
  situation = '顧客情報を大量にダウンロードしたアカウントが検知されたが、誤検知か攻撃か未確定である。',
  task = '被害を抑えつつ、後の調査に耐えられる対応を選べ（このケースで）',
  options_json = '[{"id":"a","text":"対応計画に従い責任者へ報告し、影響に応じた封じ込めと証拠保全を行い、事実と推測を分けて記録する。"},{"id":"b","text":"原因を調べる前に、関連するログや端末をすべて消去する。"},{"id":"c","text":"未確認の情報を含めて、顧客情報や事故の詳細を公開する。"},{"id":"d","text":"責任者への報告を止め、現場担当者だけで対応を続ける。"}]',
