  explanation = '初動では報告、影響評価、封じ込め、証拠保全、記録が重要である。証拠の取得経路を残し、確認済み事実と推測を区別し、終息後に再発防止を行う。',
  source_type = 'authored'
WHERE id = 'sg-scenario-incident-001' AND track_id = 'exam-sg';

UPDATE practical_scenarios SET
