('sg-scenario-jp-028', 'exam-sg', '特権アカウントの管理：権限変更後の確認', 'アクセス制御・特権管理', 'intermediate', '夜間の特権昇格要求が、チケットや作業申請とひも付いていない。', '最小権限と操作の追跡可能性を両立する方法はどれか', '[{"id":"a","text":"個人を識別できるID、必要最小限かつ期限付きの権限、承認記録、特権操作ログを組み合わせる。"},{"id":"b","text":"作業効率を優先し、管理者権限を全員へ付与する。"},{"id":"c","text":"監査を簡単にするため、全員が同じ管理者IDを使う。"},{"id":"d","text":"設定ミスを避けるため、付与済みの権限は定期的に見直さない。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', '特権は職務に必要な範囲に限定し、個人を識別できる形で付与する。承認、期限、操作ログ、定期レビューを組み合わせて追跡可能性を確保する。', 'authored'),
('sg-scenario-jp-029', 'exam-sg', '特権アカウントの管理：定期レビューでの改善', 'アクセス制御・特権管理', 'standard', '内部監査で、管理者の権限変更を独立した担当者が確認していないと指摘された。', '最小権限と操作の追跡可能性を両立する方法はどれか', '[{"id":"a","text":"作業効率を優先し、管理者権限を全員へ付与する。"},{"id":"b","text":"個人を識別できるID、必要最小限かつ期限付きの権限、承認記録、特権操作ログを組み合わせる。"},{"id":"c","text":"監査を簡単にするため、全員が同じ管理者IDを使う。"},{"id":"d","text":"設定ミスを避けるため、付与済みの権限は定期的に見直さない。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '特権は職務に必要な範囲に限定し、個人を識別できる形で付与する。承認、期限、操作ログ、定期レビューを組み合わせて追跡可能性を確保する。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-030', 'exam-sg', '個人情報の誤送信・漏えい：本番切替直前の判断', '個人情報保護', 'standard', '問い合わせ対応の画面を、個人情報が見える状態でチャットへ貼り付けた。', '個人情報の保護と被害拡大防止の観点から最も適切な行動はどれか', '[{"id":"a","text":"問題を小さく見せるため、送信記録や共有履歴を削除する。"},{"id":"b","text":"直ちに所定の窓口へ報告し、関連記録を保全したうえで、責任者が影響評価と必要な封じ込めを行う。"},{"id":"c","text":"影響確認より先に、相手の氏名や情報を社内外へ公開する。"},{"id":"d","text":"相手から苦情が届くまで待ち、対応の記録は作成しない。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '個人情報の誤送信・過剰収集・不適切共有は、速やかな報告と記録保全が必要である。影響評価、アクセス停止、相手先への連絡、法令・契約上の通知は責任者が手順に沿って判断する。', 'authored'),
('sg-scenario-jp-031', 'exam-sg', '個人情報の誤送信・漏えい：利用部門からの相談', '個人情報保護', 'standard', '利用目的を説明しないまま、業務に不要な個人情報までフォームで集めている。', '個人情報の保護と被害拡大防止の観点から最も適切な行動はどれか（このケースで）', '[{"id":"a","text":"問題を小さく見せるため、送信記録や共有履歴を削除する。"},{"id":"b","text":"影響確認より先に、相手の氏名や情報を社内外へ公開する。"},{"id":"c","text":"直ちに所定の窓口へ報告し、関連記録を保全したうえで、責任者が影響評価と必要な封じ込めを行う。"},{"id":"d","text":"相手から苦情が届くまで待ち、対応の記録は作成しない。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', '個人情報の誤送信・過剰収集・不適切共有は、速やかな報告と記録保全が必要である。影響評価、アクセス停止、相手先への連絡、法令・契約上の通知は責任者が手順に沿って判断する。', 'authored'),
('sg-scenario-jp-032', 'exam-sg', '個人情報の誤送信・漏えい：監査指摘への対応', '個人情報保護', 'standard', '開発担当者が本番の顧客データを個人PCへ複製して調査しようとしている。', '個人情報の保護と被害拡大防止の観点から最も適切な行動はどれか', '[{"id":"a","text":"問題を小さく見せるため、送信記録や共有履歴を削除する。"},{"id":"b","text":"影響確認より先に、相手の氏名や情報を社内外へ公開する。"},{"id":"c","text":"相手から苦情が届くまで待ち、対応の記録は作成しない。"},{"id":"d","text":"直ちに所定の窓口へ報告し、関連記録を保全したうえで、責任者が影響評価と必要な封じ込めを行う。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', '個人情報の誤送信・過剰収集・不適切共有は、速やかな報告と記録保全が必要である。影響評価、アクセス停止、相手先への連絡、法令・契約上の通知は責任者が手順に沿って判断する。', 'authored');

