('sg-scenario-jp-047', 'exam-sg', 'マルウェア・ランサムウェア対応：訓練後の見直し', 'マルウェア対策・封じ込め', 'intermediate', '感染端末の画面に身代金要求が表示され、社内の複数部署から問い合わせがある。', '感染拡大を抑え、復旧のための証拠を残す初動として最も適切なのはどれか', '[{"id":"a","text":"インシデント対応を起動し、承認された方法で影響端末を隔離して、ログと証拠を保全する。"},{"id":"b","text":"全端末のログとバックアップを削除し、システムを通常運用へ戻す。"},{"id":"c","text":"感染端末を社内チャットへ接続して、他の社員に原因を調べてもらう。"},{"id":"d","text":"被害の有無が確定するまで、責任者への報告を保留する。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', '疑似感染を検知したら、対応体制へ速やかに報告し、影響範囲に応じてネットワーク隔離と証拠保全を行う。無差別な削除や再接続は調査と封じ込めを妨げる。', 'authored'),
('sg-scenario-jp-048', 'exam-sg', 'マルウェア・ランサムウェア対応：サービス拡張時の判断', 'マルウェア対策・封じ込め', 'standard', '端末の異常を調べるため、利用者がログと不審ファイルを手作業で削除した。', '感染拡大を抑え、復旧のための証拠を残す初動として最も適切なのはどれか（このケースで）', '[{"id":"a","text":"全端末のログとバックアップを削除し、システムを通常運用へ戻す。"},{"id":"b","text":"インシデント対応を起動し、承認された方法で影響端末を隔離して、ログと証拠を保全する。"},{"id":"c","text":"感染端末を社内チャットへ接続して、他の社員に原因を調べてもらう。"},{"id":"d","text":"被害の有無が確定するまで、責任者への報告を保留する。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '疑似感染を検知したら、対応体制へ速やかに報告し、影響範囲に応じてネットワーク隔離と証拠保全を行う。無差別な削除や再接続は調査と封じ込めを妨げる。', 'authored'),
('sg-scenario-jp-049', 'exam-sg', 'マルウェア・ランサムウェア対応：権限変更後の確認', 'マルウェア対策・封じ込め', 'standard', '同じマルウェアを疑うアラートが海外拠点でも発生している。', '感染拡大を抑え、復旧のための証拠を残す初動として最も適切なのはどれか', '[{"id":"a","text":"全端末のログとバックアップを削除し、システムを通常運用へ戻す。"},{"id":"b","text":"感染端末を社内チャットへ接続して、他の社員に原因を調べてもらう。"},{"id":"c","text":"インシデント対応を起動し、承認された方法で影響端末を隔離して、ログと証拠を保全する。"},{"id":"d","text":"被害の有無が確定するまで、責任者への報告を保留する。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', '疑似感染を検知したら、対応体制へ速やかに報告し、影響範囲に応じてネットワーク隔離と証拠保全を行う。無差別な削除や再接続は調査と封じ込めを妨げる。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
