('sg-scenario-jp-069', 'exam-sg', '本番変更・リリース管理：権限変更後の確認', '変更管理・リリース', 'intermediate', 'リリース後の動作確認とセキュリティ確認が担当者の記憶に任されている。', '本番環境の安定性と変更の追跡可能性を確保する対応はどれか', '[{"id":"a","text":"影響評価、適切な承認と試験、バックアップ・切戻し準備、変更記録、リリース後確認を実施する。"},{"id":"b","text":"変更を急ぐため、チケットや承認を事後にも残さず直接反映する。"},{"id":"c","text":"問題が起きた場合に備え、変更前の情報やログを削除する。"},{"id":"d","text":"テストで成功したという理由だけで、本番確認と監視を省略する。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', '安全な変更管理には、影響評価、承認、検証、実施記録、切戻し計画、実施後の確認が必要である。緊急時でも正式な緊急変更手続を使う。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
