INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-090', 'exam-sg', 'クラウド共有設定の確認：権限変更後の確認', 'クラウドセキュリティ', 'standard', '退職者が所有する共有リンクとトークンを、チームが把握できていない。', 'クラウド資産への不正アクセスと情報公開を防ぐため、最も適切な行動はどれか', '[{"id":"a","text":"URLが推測しにくければ、公開設定をそのまま維持する。"},{"id":"b","text":"暗号化が有効なので、広いアクセス権や公開ポートは問題ないと判断する。"},{"id":"c","text":"公開範囲と権限を必要最小限に修正し、ログと影響を確認して、設定変更を継続的に監視する。"},{"id":"d","text":"クラウド事業者を使っているため、利用者側の設定確認を行わない。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', 'クラウドでも利用者はID、権限、データ共有、設定、監視などの責任を負う。公開範囲を是正し、過去のアクセスを調査し、継続的な設定監査を行う。', 'authored'),
('sg-scenario-jp-091', 'exam-sg', 'クラウド共有設定の確認：定期レビューでの改善', 'クラウドセキュリティ', 'standard', 'クラウド環境の設定監査結果が、担当部署の作業予定に反映されていない。', 'クラウド資産への不正アクセスと情報公開を防ぐため、最も適切な行動はどれか', '[{"id":"a","text":"URLが推測しにくければ、公開設定をそのまま維持する。"},{"id":"b","text":"暗号化が有効なので、広いアクセス権や公開ポートは問題ないと判断する。"},{"id":"c","text":"クラウド事業者を使っているため、利用者側の設定確認を行わない。"},{"id":"d","text":"公開範囲と権限を必要最小限に修正し、ログと影響を確認して、設定変更を継続的に監視する。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', 'クラウドでも利用者はID、権限、データ共有、設定、監視などの責任を負う。公開範囲を是正し、過去のアクセスを調査し、継続的な設定監査を行う。', 'authored'),
('sg-scenario-jp-092', 'exam-sg', '委託先・サプライチェーン管理：利用部門からの相談', '委託先・サプライチェーン', 'intermediate', '取引先からセキュリティ事故の連絡があり、影響範囲や報告期限が不明である。', '委託先リスクを管理し、契約・運用上の責任を明確にする対応はどれか（このケースで）', '[{"id":"a","text":"アクセス範囲と期間を限定し、契約・承認・本人別ID・ログ・事故報告・終了時の削除を確認する。"},{"id":"b","text":"納期を優先し、委託先には恒久的な管理者権限を渡す。"},{"id":"c","text":"一度委託先を選定したら、継続的な確認や再評価を行わない。"},{"id":"d","text":"契約書に書かれていない事項は、口頭合意だけで運用する。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', '委託先管理は、事前評価だけでなく、契約上の義務、アクセス制限、監督、事故連絡、再委託、データ返却・削除まで継続して行う。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
