('sg-scenario-jp-206', 'exam-sg', '情報分類・保存・最小化：権限変更後の確認', '情報資産・データ管理', 'standard', 'ファイルの分類とアクセス権が連動しておらず、公開資料と機密資料を同じ権限で扱う。', 'データの取扱いを一貫して管理する方法はどれか', '[{"id":"a","text":"ファイル名に「秘密」と書けば、共有権限や保存場所の見直しは不要とする。"},{"id":"b","text":"情報の機密度・利用目的・保存期限を明確にし、最小化、アクセス制御、適切な保存と安全な廃棄を行う。"},{"id":"c","text":"分析に便利なよう、目的に関係なく取得できる情報をすべて保存する。"},{"id":"d","text":"保存コストを減らすため、必要な証拠や保存期限も確認せずに削除する。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '情報分類はラベルだけでは不十分で、アクセス権、共有方法、暗号化、保存期間、廃棄に結び付ける。取得・利用は目的に必要な範囲に限定する。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-207', 'exam-sg', '情報分類・保存・最小化：定期レビューでの改善', '情報資産・データ管理', 'standard', '情報資産の台帳に保存場所、所有者、保存期限が登録されていない。', 'データの取扱いを一貫して管理する方法はどれか', '[{"id":"a","text":"ファイル名に「秘密」と書けば、共有権限や保存場所の見直しは不要とする。"},{"id":"b","text":"分析に便利なよう、目的に関係なく取得できる情報をすべて保存する。"},{"id":"c","text":"情報の機密度・利用目的・保存期限を明確にし、最小化、アクセス制御、適切な保存と安全な廃棄を行う。"},{"id":"d","text":"保存コストを減らすため、必要な証拠や保存期限も確認せずに削除する。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', '情報分類はラベルだけでは不十分で、アクセス権、共有方法、暗号化、保存期間、廃棄に結び付ける。取得・利用は目的に必要な範囲に限定する。', 'authored'),
('sg-scenario-jp-208', 'exam-sg', 'API認証・トークン管理：導入前の確認', 'APIセキュリティ', 'intermediate', 'APIトークンがログに出力され、複数の運用担当者が閲覧できる状態になっている。', 'API経由の不正利用を防ぐ最も適切な対策はどれか（このケースで）', '[{"id":"a","text":"利用者・操作ごとの認証認可を検証し、短寿命で必要最小限のトークンを用い、監視・制限・失効を整備する。"},{"id":"b","text":"接続先がHTTPSなら、APIの認可とトークン管理は不要と判断する。"},{"id":"c","text":"運用を簡単にするため、全利用者に同じ永続トークンを配布する。"},{"id":"d","text":"障害調査を容易にするため、トークンをログに平文保存する。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', 'APIは認証だけでなく、操作ごとの認可、トークンの期限と権限、秘密情報の保護、レート制限、監視と失効手段を設計する。HTTPSのみでは不正なアクセス権を防げない。', 'authored'),
('sg-scenario-jp-209', 'exam-sg', 'API認証・トークン管理：月次点検での対応', 'APIセキュリティ', 'standard', '外部公開APIで、呼び出し元の利用者と操作権限を検証していない。', 'API経由の不正利用を防ぐ最も適切な対策はどれか', '[{"id":"a","text":"接続先がHTTPSなら、APIの認可とトークン管理は不要と判断する。"},{"id":"b","text":"利用者・操作ごとの認証認可を検証し、短寿命で必要最小限のトークンを用い、監視・制限・失効を整備する。"},{"id":"c","text":"運用を簡単にするため、全利用者に同じ永続トークンを配布する。"},{"id":"d","text":"障害調査を容易にするため、トークンをログに平文保存する。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', 'APIは認証だけでなく、操作ごとの認可、トークンの期限と権限、秘密情報の保護、レート制限、監視と失効手段を設計する。HTTPSのみでは不正なアクセス権を防げない。', 'authored');

