INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-219', 'exam-sg', 'API認証・トークン管理：定期レビューでの改善', 'APIセキュリティ', 'standard', 'トークンの失効手順がなく、漏えい時の対応に時間がかかる。', 'API経由の不正利用を防ぐ最も適切な対策はどれか', '[{"id":"a","text":"接続先がHTTPSなら、APIの認可とトークン管理は不要と判断する。"},{"id":"b","text":"運用を簡単にするため、全利用者に同じ永続トークンを配布する。"},{"id":"c","text":"障害調査を容易にするため、トークンをログに平文保存する。"},{"id":"d","text":"利用者・操作ごとの認証認可を検証し、短寿命で必要最小限のトークンを用い、監視・制限・失効を整備する。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', 'APIは認証だけでなく、操作ごとの認可、トークンの期限と権限、秘密情報の保護、レート制限、監視と失効手段を設計する。HTTPSのみでは不正なアクセス権を防げない。', 'authored'),
('sg-scenario-jp-220', 'exam-sg', 'Webアプリケーションの脆弱性：導入前の確認', 'Web・アプリケーションセキュリティ', 'standard', '検索入力をSQL文字列へ連結しており、特殊な入力で予期しない検索結果が返る。', 'アプリケーション層の攻撃を抑える対応として最も適切なのはどれか（このケースで）', '[{"id":"a","text":"入力値をSQL文字列へ連結し、問題が発生した場合だけ修正する。"},{"id":"b","text":"サーバー側で入力と権限を検証し、パラメーター化クエリ、文脈に応じた出力エンコード、安全なセッション管理を行う。"},{"id":"c","text":"HTTPSを有効にすれば、XSSや認可不備も防げると判断する。"},{"id":"d","text":"エラー情報を詳細に公開し、攻撃者にも内部構造を見せる。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', 'Webセキュリティでは、サーバー側入力検証、パラメーター化クエリ、適切な出力エンコード、認可チェック、セッション保護、アップロード検査が必要である。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-221', 'exam-sg', 'Webアプリケーションの脆弱性：月次点検での対応', 'Web・アプリケーションセキュリティ', 'standard', 'ユーザー投稿をHTMLとして出力し、ブラウザーでスクリプトが実行される可能性がある。', 'アプリケーション層の攻撃を抑える対応として最も適切なのはどれか', '[{"id":"a","text":"入力値をSQL文字列へ連結し、問題が発生した場合だけ修正する。"},{"id":"b","text":"HTTPSを有効にすれば、XSSや認可不備も防げると判断する。"},{"id":"c","text":"サーバー側で入力と権限を検証し、パラメーター化クエリ、文脈に応じた出力エンコード、安全なセッション管理を行う。"},{"id":"d","text":"エラー情報を詳細に公開し、攻撃者にも内部構造を見せる。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', 'Webセキュリティでは、サーバー側入力検証、パラメーター化クエリ、適切な出力エンコード、認可チェック、セッション保護、アップロード検査が必要である。', 'authored'),
('sg-scenario-jp-222', 'exam-sg', 'Webアプリケーションの脆弱性：本番切替直前の判断', 'Web・アプリケーションセキュリティ', 'standard', '状態変更処理が、利用者の意図確認やCSRF対策なしに実行できる。', 'アプリケーション層の攻撃を抑える対応として最も適切なのはどれか', '[{"id":"a","text":"入力値をSQL文字列へ連結し、問題が発生した場合だけ修正する。"},{"id":"b","text":"HTTPSを有効にすれば、XSSや認可不備も防げると判断する。"},{"id":"c","text":"エラー情報を詳細に公開し、攻撃者にも内部構造を見せる。"},{"id":"d","text":"サーバー側で入力と権限を検証し、パラメーター化クエリ、文脈に応じた出力エンコード、安全なセッション管理を行う。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', 'Webセキュリティでは、サーバー側入力検証、パラメーター化クエリ、適切な出力エンコード、認可チェック、セッション保護、アップロード検査が必要である。', 'authored'),
('sg-scenario-jp-223', 'exam-sg', 'Webアプリケーションの脆弱性：利用部門からの相談', 'Web・アプリケーションセキュリティ', 'intermediate', '管理画面のURLを知っていれば、権限確認なしで他人の設定を変更できる。', 'アプリケーション層の攻撃を抑える対応として最も適切なのはどれか（このケースで）', '[{"id":"a","text":"サーバー側で入力と権限を検証し、パラメーター化クエリ、文脈に応じた出力エンコード、安全なセッション管理を行う。"},{"id":"b","text":"入力値をSQL文字列へ連結し、問題が発生した場合だけ修正する。"},{"id":"c","text":"HTTPSを有効にすれば、XSSや認可不備も防げると判断する。"},{"id":"d","text":"エラー情報を詳細に公開し、攻撃者にも内部構造を見せる。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', 'Webセキュリティでは、サーバー側入力検証、パラメーター化クエリ、適切な出力エンコード、認可チェック、セッション保護、アップロード検査が必要である。', 'authored');

