INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-299', 'exam-sg', 'IoT・制御機器の安全管理：定期レビューでの改善', 'IoT・制御システム', 'standard', '制御機器の脆弱性対応で、可用性と物理安全性への影響が検討されていない。', '情報セキュリティと設備の安全・可用性を両立する対応はどれか', '[{"id":"a","text":"業務用PCと設定を統一するため、制御機器を一般LANへ接続する。"},{"id":"b","text":"即時修正を優先し、生産・人身安全への影響を評価せずに変更する。"},{"id":"c","text":"機器・通信を把握してネットワークを分離し、保守アクセスを承認・限定し、安全性を確認したうえで変更する。"},{"id":"d","text":"ベンダー保守を簡単にするため、共有の永続的な遠隔管理権限を付与する。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', 'IoT・制御系は可用性・物理安全性・保守要件も踏まえ、資産管理、ネットワーク分離、個人別アクセス、ログ、検証済み変更を行う。', 'authored'),
('sg-scenario-jp-300', 'exam-sg', '未承認SaaS・シャドーIT：導入前の確認', 'SaaS・サービス利用管理', 'intermediate', '部門が承認を得ず、顧客情報を外部のファイル共有サービスへアップロードしている。', '業務の利便性を維持しながら、未承認サービスのリスクを管理する対応はどれか（このケースで）', '[{"id":"a","text":"利用目的・データ分類・契約・保存地域・アクセス権を評価し、承認済みサービスへ移行して不要なコピーを削除する。"},{"id":"b","text":"利用者が便利だと感じていれば、サービスの安全性や契約を確認しない。"},{"id":"c","text":"リンクを知る人が少なければ、機密資料のアップロードを継続する。"},{"id":"d","text":"サービス解約後のデータ削除やアカウント失効は事業者に任せて確認しない。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', 'SaaS導入前に、利用目的、データの種類、契約、保存地域、アクセス制御、二次利用、退出・削除を確認する。未承認利用を把握して、承認済みの安全な選択肢へ誘導する。', 'authored');

