('sg-scenario-jp-308', 'exam-sg', '未承認SaaS・シャドーIT：訓練後の見直し', 'SaaS・サービス利用管理', 'intermediate', 'SaaSの管理者権限が個人アカウントに結び付いており、組織で引き継げない。', '業務の利便性を維持しながら、未承認サービスのリスクを管理する対応はどれか', '[{"id":"a","text":"利用目的・データ分類・契約・保存地域・アクセス権を評価し、承認済みサービスへ移行して不要なコピーを削除する。"},{"id":"b","text":"利用者が便利だと感じていれば、サービスの安全性や契約を確認しない。"},{"id":"c","text":"リンクを知る人が少なければ、機密資料のアップロードを継続する。"},{"id":"d","text":"サービス解約後のデータ削除やアカウント失効は事業者に任せて確認しない。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', 'SaaS導入前に、利用目的、データの種類、契約、保存地域、アクセス制御、二次利用、退出・削除を確認する。未承認利用を把握して、承認済みの安全な選択肢へ誘導する。', 'authored'),
('sg-scenario-jp-309', 'exam-sg', '未承認SaaS・シャドーIT：サービス拡張時の判断', 'SaaS・サービス利用管理', 'standard', '部門がサービスの利用目的と保存期間を記録せず、データを長期保持している。', '業務の利便性を維持しながら、未承認サービスのリスクを管理する対応はどれか（このケースで）', '[{"id":"a","text":"利用者が便利だと感じていれば、サービスの安全性や契約を確認しない。"},{"id":"b","text":"利用目的・データ分類・契約・保存地域・アクセス権を評価し、承認済みサービスへ移行して不要なコピーを削除する。"},{"id":"c","text":"リンクを知る人が少なければ、機密資料のアップロードを継続する。"},{"id":"d","text":"サービス解約後のデータ削除やアカウント失効は事業者に任せて確認しない。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', 'SaaS導入前に、利用目的、データの種類、契約、保存地域、アクセス制御、二次利用、退出・削除を確認する。未承認利用を把握して、承認済みの安全な選択肢へ誘導する。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-310', 'exam-sg', '未承認SaaS・シャドーIT：権限変更後の確認', 'SaaS・サービス利用管理', 'standard', '利用規約が変更され、データの二次利用条件が以前と異なっている。', '業務の利便性を維持しながら、未承認サービスのリスクを管理する対応はどれか', '[{"id":"a","text":"利用者が便利だと感じていれば、サービスの安全性や契約を確認しない。"},{"id":"b","text":"リンクを知る人が少なければ、機密資料のアップロードを継続する。"},{"id":"c","text":"利用目的・データ分類・契約・保存地域・アクセス権を評価し、承認済みサービスへ移行して不要なコピーを削除する。"},{"id":"d","text":"サービス解約後のデータ削除やアカウント失効は事業者に任せて確認しない。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', 'SaaS導入前に、利用目的、データの種類、契約、保存地域、アクセス制御、二次利用、退出・削除を確認する。未承認利用を把握して、承認済みの安全な選択肢へ誘導する。', 'authored'),
('sg-scenario-jp-311', 'exam-sg', '未承認SaaS・シャドーIT：定期レビューでの改善', 'SaaS・サービス利用管理', 'standard', '承認済みツールがあるのに、別の未承認サービスへ資料を再アップロードしている。', '業務の利便性を維持しながら、未承認サービスのリスクを管理する対応はどれか', '[{"id":"a","text":"利用者が便利だと感じていれば、サービスの安全性や契約を確認しない。"},{"id":"b","text":"リンクを知る人が少なければ、機密資料のアップロードを継続する。"},{"id":"c","text":"サービス解約後のデータ削除やアカウント失効は事業者に任せて確認しない。"},{"id":"d","text":"利用目的・データ分類・契約・保存地域・アクセス権を評価し、承認済みサービスへ移行して不要なコピーを削除する。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', 'SaaS導入前に、利用目的、データの種類、契約、保存地域、アクセス制御、二次利用、退出・削除を確認する。未承認利用を把握して、承認済みの安全な選択肢へ誘導する。', 'authored'),
('sg-scenario-jp-312', 'exam-sg', '生成AIの安全な利用：導入前の確認', '生成AI・データ保護', 'standard', '社員が顧客の氏名・契約条件を外部生成AIの入力欄へ貼り付けてしまった。', '生成AIの有用性を保ちながら、情報漏えいと誤判断を抑える方法はどれか（このケースで）', '[{"id":"a","text":"処理効率を優先し、機密情報や個人情報を制限なく入力する。"},{"id":"b","text":"承認済み環境とデータ利用ルールを使い、入力情報を最小化し、出力を人が検証して利用履歴を管理する。"},{"id":"c","text":"AIが自然な文章を返した場合、事実確認や法務確認を省略する。"},{"id":"d","text":"連携機能をすべて許可し、最小権限や監査を適用しない。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '生成AI利用では、入力データの分類・最小化、承認済みサービス、契約条件、出力検証、権限制御、ログ、プロンプト攻撃への対策を整える。', 'authored');

