('sg-scenario-jp-320', 'exam-sg', '生成AIの安全な利用：訓練後の見直し', '生成AI・データ保護', 'standard', 'AIで作成した要約が元資料を誤って表現し、重要な意思決定に使われようとしている。', '生成AIの有用性を保ちながら、情報漏えいと誤判断を抑える方法はどれか', '[{"id":"a","text":"処理効率を優先し、機密情報や個人情報を制限なく入力する。"},{"id":"b","text":"承認済み環境とデータ利用ルールを使い、入力情報を最小化し、出力を人が検証して利用履歴を管理する。"},{"id":"c","text":"AIが自然な文章を返した場合、事実確認や法務確認を省略する。"},{"id":"d","text":"連携機能をすべて許可し、最小権限や監査を適用しない。"}]', 'b', '{"a":35,"b":100,"c":15,"d":0}', '生成AI利用では、入力データの分類・最小化、承認済みサービス、契約条件、出力検証、権限制御、ログ、プロンプト攻撃への対策を整える。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
