VALUES
('sg-scenario-jp-321', 'exam-sg', '生成AIの安全な利用：サービス拡張時の判断', '生成AI・データ保護', 'standard', '社外向け文書をAIで生成したが、人によるレビューと出典確認が行われていない。', '生成AIの有用性を保ちながら、情報漏えいと誤判断を抑える方法はどれか（このケースで）', '[{"id":"a","text":"処理効率を優先し、機密情報や個人情報を制限なく入力する。"},{"id":"b","text":"AIが自然な文章を返した場合、事実確認や法務確認を省略する。"},{"id":"c","text":"承認済み環境とデータ利用ルールを使い、入力情報を最小化し、出力を人が検証して利用履歴を管理する。"},{"id":"d","text":"連携機能をすべて許可し、最小権限や監査を適用しない。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', '生成AI利用では、入力データの分類・最小化、承認済みサービス、契約条件、出力検証、権限制御、ログ、プロンプト攻撃への対策を整える。', 'authored'),
('sg-scenario-jp-322', 'exam-sg', '生成AIの安全な利用：権限変更後の確認', '生成AI・データ保護', 'standard', '生成AIの連携プラグインが、業務メールの全件読み取り権限を要求している。', '生成AIの有用性を保ちながら、情報漏えいと誤判断を抑える方法はどれか', '[{"id":"a","text":"処理効率を優先し、機密情報や個人情報を制限なく入力する。"},{"id":"b","text":"AIが自然な文章を返した場合、事実確認や法務確認を省略する。"},{"id":"c","text":"連携機能をすべて許可し、最小権限や監査を適用しない。"},{"id":"d","text":"承認済み環境とデータ利用ルールを使い、入力情報を最小化し、出力を人が検証して利用履歴を管理する。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', '生成AI利用では、入力データの分類・最小化、承認済みサービス、契約条件、出力検証、権限制御、ログ、プロンプト攻撃への対策を整える。', 'authored'),
('sg-scenario-jp-323', 'exam-sg', '生成AIの安全な利用：定期レビューでの改善', '生成AI・データ保護', 'intermediate', 'AIの利用記録が残らず、どの情報を入力して結果をどう使ったか追跡できない。', '生成AIの有用性を保ちながら、情報漏えいと誤判断を抑える方法はどれか', '[{"id":"a","text":"承認済み環境とデータ利用ルールを使い、入力情報を最小化し、出力を人が検証して利用履歴を管理する。"},{"id":"b","text":"処理効率を優先し、機密情報や個人情報を制限なく入力する。"},{"id":"c","text":"AIが自然な文章を返した場合、事実確認や法務確認を省略する。"},{"id":"d","text":"連携機能をすべて許可し、最小権限や監査を適用しない。"}]', 'a', '{"a":100,"b":35,"c":15,"d":0}', '生成AI利用では、入力データの分類・最小化、承認済みサービス、契約条件、出力検証、権限制御、ログ、プロンプト攻撃への対策を整える。', 'authored');

INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-jp-324', 'exam-sg', 'ヘルプデスクの本人確認：導入前の確認', '本人確認・ソーシャルエンジニアリング', 'standard', '電話相手が役員を名乗り、通常手順を省略してパスワードリセットを要求している。', 'なりすましによる不正なアカウント回復を防ぐ対応はどれか（このケースで）', '[{"id":"a","text":"役職や緊急性が高そうなら、本人確認を省略して処理する。"},{"id":"b","text":"相手が提示した個人情報だけを根拠に、認証要素を変更する。"},{"id":"c","text":"定められた本人確認を独立した信頼できる手段で実施し、必要な承認・記録・試行制限を守る。"},{"id":"d","text":"利用者の利便性を優先し、認証コードや一時パスワードを相手に口頭で伝える。"}]', 'c', '{"a":35,"b":15,"c":100,"d":0}', '表示名や既知の個人情報だけでは本人確認にならない。標準手順、独立した連絡経路、承認、試行制限、操作記録を組み合わせ、緊急要求でも例外を管理する。', 'authored'),
('sg-scenario-jp-325', 'exam-sg', 'ヘルプデスクの本人確認：月次点検での対応', '本人確認・ソーシャルエンジニアリング', 'standard', '問い合わせ者が、本人しか知らないはずの個人情報を提示して認証を求めている。', 'なりすましによる不正なアカウント回復を防ぐ対応はどれか', '[{"id":"a","text":"役職や緊急性が高そうなら、本人確認を省略して処理する。"},{"id":"b","text":"相手が提示した個人情報だけを根拠に、認証要素を変更する。"},{"id":"c","text":"利用者の利便性を優先し、認証コードや一時パスワードを相手に口頭で伝える。"},{"id":"d","text":"定められた本人確認を独立した信頼できる手段で実施し、必要な承認・記録・試行制限を守る。"}]', 'd', '{"a":35,"b":15,"c":0,"d":100}', '表示名や既知の個人情報だけでは本人確認にならない。標準手順、独立した連絡経路、承認、試行制限、操作記録を組み合わせ、緊急要求でも例外を管理する。', 'authored'),
